script:
carrier_event = {
	id = colony.1
	title = "colony.1.name"
	desc = "colony.1.desc"
	picture = GFX_evt_alien_nature
	show_sound = event_alien_nature
	location = ROOT
	trackable = yes
	event_chain = migrating_forests_chain

	pre_triggers = {
		has_owner = yes
		is_homeworld = no
		original_owner = yes
		is_ai = no
		has_ground_combat = no
		is_capital = no
		is_occupied_flag = no
	}

	trigger = {
		NOT = { is_planet_class = pc_volcanic }
		owner = {
			is_machine_empire = no
			is_wilderness_empire = no
		}
		pop_amount > 0
		OR = {
			is_planet_class = pc_continental
			is_planet_class = pc_tropical
			is_planet_class = pc_arid
			is_planet_class = pc_tundra
			is_planet_class = pc_savannah
		}
		NOR = {
			has_global_flag = migrating_forests_global
			has_carrier_flag = colony_event
		}
	}

	is_triggered_only = yes

	immediate = {
		set_global_flag = migrating_forests_global
		set_carrier_flag = colony_event
		add_deposit = d_migrating_forests
		add_modifier = {
			modifier = "migrating_forests"
			days = -1
		}
		begin_event_chain = {
			event_chain = "migrating_forests_chain"
			target = ROOT
		}
	}

	option = {
		name = colony.1.a
		tooltip = {
			add_deposit = d_migrating_forests
			begin_event_chain = {
				event_chain = "migrating_forests_chain"
				target = ROOT
			}
		}
		enable_special_project = {
			name = "MIGRATING_FORESTS_1_PROJECT"
			location = this
			owner = root
		}
		if = {
			limit = {
				owner = { NOT = { has_civic = civic_environmentalist } }
			}
			enable_special_project = {
				name = "MIGRATING_FORESTS_2_PROJECT"
				location = this
				owner = root
			}
		}
	}

	after = {
		carrier_event = { id = colony.12 days = 180 random = 2400 }
	}
}

