script:
carrier_event = {
	id = colony.4
	title = "colony.4.name"
	desc = "colony.4.desc"
	picture = GFX_evt_alien_nature
	show_sound = event_air_raid_siren
	location = ROOT
	event_chain = migrating_forests_chain
	is_triggered_only = yes

	auto_opens = yes

	pre_triggers = {
		has_owner = yes
		is_homeworld = no
		original_owner = yes
		has_ground_combat = no
	}

	trigger = {
		NOT = { has_carrier_flag = burned_forests_rampage }
		has_carrier_flag = burned_forests
		pop_amount > 0
	}

	immediate = {
		set_carrier_flag = burned_forests_rampage
		set_carrier_flag = burned_forests_rampaged_planet
		owner = { set_country_flag = burned_forests_rampaged_country }
		create_country = {
			name = "NAME_Rampaging_Forests"
			type = faction
			effect = {
				establish_communications_no_message = root.owner
				establish_contact = { who = root.owner location = root.solar_system }
			}
		}
		create_species = {
			name = "NAME_Migrating_Trees"
			class = random_non_machine
			portrait = random
			traits = random
		}
		create_army = {
			name = "NAME_Rampaging_Forest"
			owner = last_created_country
			species = last_created_species
			type = "tree_army"
		}
		create_army = {
			name = "NAME_Rampaging_Forest"
			owner = last_created_country
			species = last_created_species
			type = "tree_army"
		}
		create_army = {
			name = "NAME_Rampaging_Forest"
			owner = last_created_country
			species = last_created_species
			type = "tree_army"
		}
		set_planet_purge_type = purge_displacement
	}

	option = {
		name = colony.4.a
		custom_tooltip = tree_armies
	}
}

