script:
country_event = {
	id = colony.113
	title = "colony.113.name"
	desc = "colony.113.desc"
	picture = GFX_evt_burning_settlement
	show_sound = event_ghost_town
	location = FROMFROM

	is_triggered_only = yes

	trigger = {
		has_country_flag = terraforming_mutants_invade_country
		FROMFROM = { planet = { has_carrier_flag = terraforming_mutants_invade_planet } }
	}

	immediate = {
		FROMFROM = {
			set_carrier_flag = terraforming_mutants_won
			remove_carrier_flag = terraforming_mutants_invade_planet
			create_pop_group = {
				species = owner.species
				category = purge
				effect = {
					save_event_target_as = purge_pop_group
					set_pop_group_flag = event_purge
				}
			}
			every_owned_pop_group = {
				limit = {
					NOT = { is_same_value = event_target:purge_pop_group }
				}
				transfer_pop_amount = {
					source = this
					target = event_target:purge_pop_group
					percentage = 1
				}
			}
		}
	}

	option = {
		name = colony.113.a
	}
}

