script:
country_event = {
	id = colony.114
	title = "colony.114.name"
	desc = "colony.114.desc"
	picture = GFX_evt_victorious_army
	show_sound = event_ground_battle
	location = FROMFROM

	is_triggered_only = yes

	trigger = {
		has_country_flag = terraforming_mutants_invade_country
		FROMFROM = { planet = { has_carrier_flag = terraforming_mutants_won } }
	}

	immediate = {
		remove_country_flag = terraforming_mutants_invade_country
		FROMFROM = {
			set_carrier_flag = terraforming_mutants_defeated
			remove_carrier_flag = terraforming_mutants_won
			set_owner = ROOT
			clear_planet_purge_type = yes
			create_pop_group = {
				species = owner.species
				category = civilian
				effect = {
					save_event_target_as = non_purge_pop_group
				}
			}
			every_owned_pop_group = {
				limit = {
					has_pop_group_flag = event_purge
					NOT = { is_same_value = event_target:non_purge_pop_group }
				}
				transfer_pop_amount = {
					source = this
					target = event_target:non_purge_pop_group
					percentage = 1
				}
			}

			every_owned_pop_group = {
				remove_modifier = "pop_recently_conquered"
				add_modifier = {
					modifier = "pop_liberation_fever"
					days = 3600
				}
			}
		}
	}

	option = {
		name = colony.114.a
	}
}

